import{_ as o,o as e,c as t,a3 as r}from"./chunks/framework.DH7DibUz.js";const u=JSON.parse('{"title":"Packaging Workshop (Python and Julia)","description":"","frontmatter":{"title":"Packaging Workshop (Python and Julia)","date":"2024-02-20T00:00:00.000Z","author":"Ludovic Räss","tags":["Workshop","Event","Git","Julia","Python"]},"headers":[],"relativePath":"events/pkg-workshop.md","filePath":"events/pkg-workshop.md","lastUpdated":1794345340000}'),i={name:"events/pkg-workshop.md"};function n(l,a,h,s,p,g){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="packaging-workshop-python-and-julia" tabindex="-1">Packaging Workshop (Python and Julia) <a class="header-anchor" href="#packaging-workshop-python-and-julia" aria-label="Permalink to &quot;Packaging Workshop (Python and Julia)&quot;">​</a></h1><h2 id="workshop-info" tabindex="-1">Workshop info <a class="header-anchor" href="#workshop-info" aria-label="Permalink to &quot;Workshop info&quot;">​</a></h2><blockquote><p>This is an announcement for a brand new course provided by the <a href="https://www.unil.ch/ci/dcsr-en" target="_blank" rel="noreferrer">DCSR</a> and the Swiss Geocomputing Center <a href="https://unil-sgc.github.io" target="_blank" rel="noreferrer">SGC</a>.</p></blockquote><p>The aim of this workshop is to cover the broad &quot;packaging&quot; topic. We will use examples in Python and Julia and guide you through the process of transitioning from a standalone Jupyter notebook to a small package.</p><p>🔎 The venue is Geopolis room <strong>GEO 2137</strong></p><p>⌚ February Tuesday 20th from 10h to 16h.</p><p>The link to register is was sent out to Unil community via email. The language is English. No online option will be available.</p><h2 id="program" tabindex="-1">Program <a class="header-anchor" href="#program" aria-label="Permalink to &quot;Program&quot;">​</a></h2><ul><li><strong>10h - 10h30/45</strong>: Introduction to good practices <ul><li>reproducible environments, documentation, version control</li><li>why and when create a Package</li></ul></li><li><strong>10h45 - 12h45</strong>: <a href="https://github.com/Unil-SGC/python-packaging" target="_blank" rel="noreferrer">Python Packaging</a><ul><li>transform your jupyter notebook into a python script</li><li>create a Python package from this python script</li><li>share the package</li></ul></li><li><strong>12h45 - 14h</strong>: Lunch break</li><li><strong>14h - 16h</strong>: <a href="https://github.com/Unil-SGC/julia-packaging" target="_blank" rel="noreferrer">Julia Packaging</a><ul><li>transform your Julia jupyter notebook into a Julia script</li><li>create a Julia package from this Julia script</li><li>share the package</li></ul></li></ul><h2 id="material" tabindex="-1">Material <a class="header-anchor" href="#material" aria-label="Permalink to &quot;Material&quot;">​</a></h2><p>Slides and other assets including codes and packages can be found here:</p><ul><li><a href="https://github.com/Unil-SGC/python-packaging" target="_blank" rel="noreferrer">Python packaging (https://github.com/Unil-SGC/python-packaging)</a></li><li><a href="https://github.com/Unil-SGC/julia-packaging" target="_blank" rel="noreferrer">Julia packaging (https://github.com/Unil-SGC/julia-packaging)</a></li></ul>',12)])])}const k=o(i,[["render",n]]);export{u as __pageData,k as default};
